42	type sdkDetector struct {
43		newResource func(context.Context, ...resource.Option) (*resource.Resource, error)
44		option      func() resource.Option
45	}
46	
47	// Detect returns resource information from the configured SDK detector option.
48	func (d *sdkDetector) Detect(ctx context.Context) (*resource.Resource, error) {
49		res, err := d.newResource(ctx, d.option())
50		if err != nil {
51			return nil, err
52		}
53		// Strip schema URL to avoid conflicts - it will be set at the resource level.
54		return resource.New(ctx, resource.WithAttributes(res.Attributes()...))
55	}
56	
57	// GetDetector returns a resource.Detector for the given detector name.
58	// Returns an error if the detector name is not recognized.
59	func GetDetector(ctx context.Context, name string) (resource.Detector, error) {
60		factory, ok := detectorRegistry[name]
61		if !ok {
62			supportedDetectors := make([]string, 0, len(detectorRegistry))
63			for detectorName := range detectorRegistry {
64				supportedDetectors = append(supportedDetectors, detectorName)
65			}
66			sort.Strings(supportedDetectors)
67			return nil, fmt.Errorf("unknown detector: %q. Supported detectors: %s", name, strings.Join(supportedDetectors, ", "))
68		}
69		return factory(ctx)
70	}
71	
72	// GetDetectors returns a slice of resource.Detector instances for the given detector names.
73	func GetDetectors(ctx context.Context, names []string) ([]resource.Detector, error) {
74		if len(names) == 0 {
75			return nil, nil
76		}
77	
78		detectors := make([]resource.Detector, 0, len(names))
79		for _, name := range names {
80			detector, err := GetDetector(ctx, name)
81			if err != nil {
82				return nil, err
83			}
84			detectors = append(detectors, detector)
85		}
86		return detectors, nil
87	}
