// ResourceConfigV030 represents the v0.3.0 resource configuration with
// backward-compatible support for the legacy inline resource attribute map
// format that was used before declarative configuration.
//
// The embedded config.Resource promotes the declarative fields (Attributes,
// SchemaUrl, Detectors, AttributesList) via mapstructure squash, while any
// unknown keys are captured into LegacyAttributes via mapstructure remain.
// The legacy format uses string values as attribute overrides and nil values
// to remove the corresponding default attribute from the resource.
type ResourceConfigV030 struct {
	config.Resource `mapstructure:",squash"`

	// LegacyAttributes captures the legacy inline resource attribute map
	// format, where each key maps to either a string override or nil (to
	// remove the corresponding default attribute). Keys with a nil value are
	// not stored here.
	LegacyAttributes map[string]any `mapstructure:",remain"`
}

func (r *ResourceConfigV030) Unmarshal(conf *confmap.Conf) error {
	if err := conf.Unmarshal(r); err != nil {
		return err
	}
	// The legacy inline format uses a nil value to indicate that a default
	// attribute should be removed. Such keys must not be stored in
	// LegacyAttributes.
	for k, v := range r.LegacyAttributes {
		if v == nil {
			delete(r.LegacyAttributes, k)
		}
	}
	if len(r.LegacyAttributes) == 0 {
		r.LegacyAttributes = nil
	}
	return nil
}

func (r *ResourceConfigV030) Validate() error {
	// resource::attributes_list is part of the otelconf declarative schema,
	// but it is not currently supported by the collector because it would
	// interact in surprising ways with the default attributes placed under
	// resource::attributes.
	if r.AttributesList != nil {
		return errors.New("resource::attributes_list is not currently supported")
	}

	// mapstructure ",remain" only supports map[string]any, but the legacy
	// format is conceptually map[string]*string: only string and null values
	// are valid.
	for k, v := range r.LegacyAttributes {
		if v == nil {
			continue
		}
		if _, ok := v.(string); !ok {
			return fmt.Errorf("legacy inline resource attribute %q must be a string or null, got %T", k, v)
		}
	}

	if len(r.Attributes) > 0 && len(r.LegacyAttributes) > 0 {
		return errors.New("resource::attributes cannot be used together with legacy inline resource attributes")
	}

	return nil
}
