// errMissingCollectorResource is returned when a telemetry provider is created
// without a resource having first been created and passed through the settings.
var errMissingCollectorResource = errors.New("no collector resource provided in telemetry settings")

// defaultAttributeValues returns the default resource attributes for the given
// build info. It is a variable so that it can be replaced in tests.
var defaultAttributeValues = func(buildInfo component.BuildInfo) (map[string]string, error) {
	instanceUUID, err := uuid.NewRandom()
	if err != nil {
		return nil, err
	}
	return map[string]string{
		string(semconv.ServiceNameKey):       buildInfo.Command,
		string(semconv.ServiceVersionKey):    buildInfo.Version,
		string(semconv.ServiceInstanceIDKey): instanceUUID.String(),
	}, nil
}

// CreateResource creates a pcommon.Resource from the given settings and Config.
//
// A new, independent resource is created on each call; resources are never
// cached or shared across invocations.
func (f *Factory) CreateResource(
	ctx context.Context,
	set telemetry.Settings,
	cfg *Config,
) (pcommon.Resource, error) {
	resourceConfig, err := createInitialResourceConfig(set.BuildInfo, &cfg.Resource)
	if err != nil {
		return pcommon.Resource{}, err
	}

	// Build an SDK from the resource configuration so that attribute values
	// are converted following the otelconf rules, then copy the resulting
	// resource attributes into a pcommon.Resource.
	sdk, err := config.NewSDK(
		config.WithContext(ctx),
		config.WithOpenTelemetryConfiguration(config.OpenTelemetryConfiguration{
			Resource: resourceConfig,
		}),
	)
	if err != nil {
		return pcommon.Resource{}, err
	}

	res := pcommon.NewResource()
	if sdkRes := sdk.Resource(); sdkRes != nil {
		for _, attr := range sdkRes.Attributes() {
			putAttributeValue(res.Attributes(), string(attr.Key), attr.Value)
		}
	}
	return res, nil
}

// createInitialResourceConfig combines the default attribute values with the
// resource configuration, producing an otelconf resource config.
//
// Default attributes are excluded when their name is set in the legacy inline
// format (even with a nil value) or provided as a declarative attribute. Non-nil
// legacy attributes and declarative attributes are then appended.
func createInitialResourceConfig(buildInfo component.BuildInfo, cfg *migration.ResourceConfigV030) (*config.Resource, error) {
	defaults, err := defaultAttributeValues(buildInfo)
	if err != nil {
		return nil, err
	}

	// Determine which default attributes are overridden or removed.
	provided := make(map[string]struct{}, len(cfg.LegacyAttributes)+len(cfg.Attributes))
	for k := range cfg.LegacyAttributes {
		provided[k] = struct{}{}
	}
	for _, attr := range cfg.Attributes {
		provided[attr.Name] = struct{}{}
	}

	attrs := make([]config.AttributeNameValue, 0, len(defaults)+len(cfg.LegacyAttributes)+len(cfg.Attributes))

	// Add the default attributes that were not overridden or removed, in a
	// deterministic order.
	defaultKeys := make([]string, 0, len(defaults))
	for k := range defaults {
		if _, ok := provided[k]; ok {
			continue
		}
		defaultKeys = append(defaultKeys, k)
	}
	sort.Strings(defaultKeys)
	for _, k := range defaultKeys {
		attrs = append(attrs, config.AttributeNameValue{Name: k, Value: defaults[k]})
	}

	// Append the non-nil legacy attributes, in a deterministic order.
	legacyKeys := make([]string, 0, len(cfg.LegacyAttributes))
	for k := range cfg.LegacyAttributes {
		legacyKeys = append(legacyKeys, k)
	}
	sort.Strings(legacyKeys)
	for _, k := range legacyKeys {
		if v := cfg.LegacyAttributes[k]; v != nil {
			attrs = append(attrs, config.AttributeNameValue{Name: k, Value: v})
		}
	}

	// Append the declarative attributes.
	attrs = append(attrs, cfg.Attributes...)

	schemaURL := cfg.SchemaUrl
	if schemaURL == nil {
		schemaURL = ptr(semconv.SchemaURL)
	}
	return &config.Resource{
		SchemaUrl:  schemaURL,
		Attributes: attrs,
	}, nil
}

// createFixedResourceConfig converts an already-resolved pcommon.Resource into
// an otelconf resource config, carrying over the SchemaUrl from the resource
// configuration.
func createFixedResourceConfig(cfg *migration.ResourceConfigV030, res *pcommon.Resource) (*config.Resource, error) {
	if res == nil {
		return nil, errMissingCollectorResource
	}
	attrs := make([]config.AttributeNameValue, 0, res.Attributes().Len())
	res.Attributes().Range(func(k string, v pcommon.Value) bool {
		attrs = append(attrs, config.AttributeNameValue{Name: k, Value: v.AsRaw()})
		return true
	})
	return &config.Resource{
		SchemaUrl:  cfg.SchemaUrl,
		Attributes: attrs,
	}, nil
}

// putAttributeValue stores an OpenTelemetry attribute value into a pcommon.Map,
// preserving the value type.
func putAttributeValue(m pcommon.Map, k string, v attribute.Value) {
	switch v.Type() {
	case attribute.BOOL:
		m.PutBool(k, v.AsBool())
	case attribute.INT64:
		m.PutInt(k, v.AsInt64())
	case attribute.FLOAT64:
		m.PutDouble(k, v.AsFloat64())
	case attribute.STRING:
		m.PutStr(k, v.AsString())
	default:
		m.PutStr(k, v.Emit())
	}
}

func attributeValueString(k string, v attribute.Value) (string, error) {
	if v.Type() != attribute.STRING {
		// We only support string-type resource attributes in the configuration.
		return "", fmt.Errorf("attribute %q: expected string, got %s", k, v.Type())
	}
	return v.AsString(), nil
}
